from funcy import decorator

@decorator
def logged(call, *args, **kwargs):
    print(f"Calling {call.__name__}")
    return call(*args, **kwargs)

# Test with kwonly
def test_kwonly(a, b, *, c=1):
    return a + b + c

try:
    result = logged(test_kwonly)(1, 2, c=3)
    print(f"result: {result}")
except Exception as e:
    print(f"Error: {type(e).__name__}: {e}")

# Try calling directly with kwargs
try:
    result = logged(test_kwonly)(1, 2, **{'c': 3})
    print(f"result: {result}")
except Exception as e:
    print(f"Error: {type(e).__name__}: {e}")
EOF
